mapper.select:
SELECT id, system_level, system_name, owner_name, mobile,
       monitor_edition, write_jdbc_key
FROM zabbix.sla_system_owner
WHERE system_level = #{systemLevel}
  AND system_name = #{systemName}
LIMIT 1

mapper.update:
UPDATE zabbix.sla_system_owner
SET monitor_edition = #{monitorEdition},
    write_jdbc_key = #{writeJdbcKey}
WHERE system_level = #{systemLevel}
  AND system_name = #{systemName}
